package io.asv.odinlab;
import android.app.Activity;import android.os.Bundle;import android.content.Intent;import android.net.Uri;import android.graphics.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
public class RiftPhotoActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private volatile boolean alive=true;private boolean busy;private LiveEngine engine;private LinearLayout results;private TextView status;private Button open,demo;private final List<Bitmap> thumbs=new ArrayList<>();
 public void onCreate(Bundle state){super.onCreate(state);LinearLayout col=new LinearLayout(this);col.setOrientation(LinearLayout.VERTICAL);col.setPadding(24,32,24,24);TextView title=new TextView(this);title.setText(R.string.rift_title);col.addView(title);TextView help=new TextView(this);help.setText(R.string.rift_help);col.addView(help);open=new Button(this);open.setText(R.string.rift_open);col.addView(open);demo=new Button(this);demo.setText(R.string.rift_demo);col.addView(demo);status=new TextView(this);col.addView(status);results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);col.addView(results);ScrollView scroll=new ScrollView(this);scroll.addView(col);setContentView(scroll);
 open.setOnClickListener(v->{if(busy)return;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(intent,61);});demo.setOnClickListener(v->process(null));}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==61&&result==RESULT_OK&&data!=null&&data.getData()!=null)process(data.getData());}
 private void process(Uri uri){if(busy)return;busy=true;open.setEnabled(false);demo.setEnabled(false);status.setText(R.string.rift_busy);results.removeAllViews();for(Bitmap b:thumbs)b.recycle();thumbs.clear();worker.execute(()->{Bitmap frame=null;File dir=new File(getFilesDir(),"rift-photos/"+UUID.randomUUID());try{if(!dir.mkdirs())throw new IOException("mkdir");File original=new File(dir,"original");try(InputStream in=uri==null?getAssets().open("multi16.png"):getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Input unavailable");java.nio.file.Files.copy(in,original.toPath());}
 frame=ImageDecoder.decodeBitmap(ImageDecoder.createSource(original),(decoder,info,source)->{decoder.setAllocator(ImageDecoder.ALLOCATOR_SOFTWARE);int w=info.getSize().getWidth(),h=info.getSize().getHeight();double scale=Math.min(1,2048.0/Math.max(w,h));decoder.setTargetSize(Math.max(1,(int)(w*scale)),Math.max(1,(int)(h*scale)));});if(engine==null)engine=new LiveEngine(getApplicationContext());JSONObject report=RiftPhotoRun.run(getApplicationContext(),engine,frame,dir);runOnUiThread(()->{if(!alive)return;try{StringBuilder text=new StringBuilder();JSONArray rows=report.getJSONArray("rows");for(int r=0;r<rows.length();r++){JSONObject row=rows.getJSONObject(r);JSONArray cards=row.getJSONArray("cards");text.append(row.getString("detector")).append(": ").append(cards.length()).append(" · ").append(Math.round(row.getDouble("detect_ms"))).append(" ms\n");for(int i=0;i<cards.length();i++){JSONObject card=cards.getJSONObject(i);TextView label=new TextView(this);label.setText(row.getString("detector")+" #"+(i+1)+" · "+card.getJSONObject("diego").getJSONArray("top").getJSONObject(0).getString("label"));results.addView(label);BitmapFactory.Options opts=new BitmapFactory.Options();opts.inSampleSize=4;Bitmap thumb=BitmapFactory.decodeFile(new File(dir,card.getString("crop")).toString(),opts);thumbs.add(thumb);ImageView view=new ImageView(this);view.setAdjustViewBounds(true);view.setImageBitmap(thumb);results.addView(view);}}status.setText(getString(R.string.rift_done,dir.getName(),text.toString()));}catch(Exception e){status.setText(e.toString());}});
 }catch(Exception e){try{CaptureEngine.save(dir,"error.json",new JSONObject().put("error",e.toString()));}catch(Exception ignored){}runOnUiThread(()->{if(alive)status.setText(e.toString());});}finally{if(frame!=null)frame.recycle();runOnUiThread(()->{if(alive){busy=false;open.setEnabled(true);demo.setEnabled(true);}});}});}
 protected void onDestroy(){alive=false;worker.execute(()->{if(engine!=null)engine.close();});worker.shutdown();results.removeAllViews();for(Bitmap b:thumbs)b.recycle();super.onDestroy();}
}
